    buyRule: '优先观察澜起科技能否守住HK$266.60—266.00并突破HK$283.80；这是当日唯一由最新正式多方接管且获收盘确认的标的。其余A股须先收复各自完整空方信号带，再突破MA5或当日高点才进入右侧修复。长鑫科技需站上¥58.27，国民技术H需站上HK$9.045，白银需站稳$63.46并突破现货日高$63.61；贴价、区间中部和首根反抽均不追。',
